-- Corrections du quiz de fin de semaine : observer.
--
-- Générées par scripts/importer-quiz.mjs. `data` porte la version adulte, 
-- `data.version_enfant` la version enfant du même sujet. Remplace `version_moniteur`
-- (même rôle, jamais exploité par un vrai choix au lancement avant ce jour).

DELETE FROM game_cards WHERE id = '51296875-a227-46e2-b122-eff8a6ccc510';
UPDATE game_cards SET related_objective_id = '71', data = '{"question":"Qu''est-ce qu''un amer, et pourquoi le repérer avant de partir sur l''eau ?","answers":["Un courant côtier dangereux — inutile de le repérer","Un point fixe et visible à terre (clocher, phare) qui permet de se situer même si les conditions changent","La profondeur minimale d''un chenal","Un signal sonore de brume"],"correctAnswerIndex":1,"explanation":"Un amer reste visible même quand on perd ses repères en mer. En croiser deux permet de savoir précisément où l''on se trouve — utile même si le GPS tombe en panne.","version_enfant":{"question":"Pourquoi choisir un repère fixe à terre avant de partir sur l''eau ?","answers":["Pour savoir où on est, même si on dérive ou si on ne voit plus bien","Pour impressionner les autres","Pour mesurer la vitesse du courant","Pour connaître la hauteur des vagues"],"correctAnswerIndex":0,"explanation":"Un amer, c''est un repère fixe et visible de loin — un clocher, un phare. Ça permet de savoir où on est, même si on a dérivé."}}'::jsonb WHERE id = '3ded4e32-4057-4566-84d8-17a27bb9903d';
UPDATE game_cards SET related_objective_id = '69', data = '{"question":"Pourquoi les éléments du milieu marin sont-ils interdépendants ?","answers":["Ce n''est pas le cas — chaque espèce vit indépendamment","Le vent crée les vagues, qui façonnent la côte, qui abrite des espèces : tout est lié","Seuls le vent et les marées sont liés","L''interdépendance ne concerne que les espèces animales"],"correctAnswerIndex":1,"explanation":"Le vent crée des vagues, les vagues érodent la côte, la forme de côte abrite des espèces qui attirent d''autres animaux. Modifier un élément impacte tout le système.","version_enfant":{"question":"Le vent, l''eau, le sable et les animaux, c''est lié entre eux ?","answers":["Non, chacun vit de son côté","Oui, tout est relié : changer une chose déplace tout le reste","Seulement le vent et l''eau sont liés","Seulement les animaux entre eux"],"correctAnswerIndex":1,"explanation":"Ici, tout est relié : le vent pousse le sable, une plante le retient, un animal s''y abrite. Changer une chose déplace tout le reste."}}'::jsonb WHERE id = 'd3a08232-c462-45c5-9594-1e6bd5040530';
UPDATE game_cards SET related_objective_id = '68', data = '{"question":"Pourquoi les activités humaines doivent-elles s''adapter aux rythmes naturels du littoral ?","answers":["C''est une obligation légale uniquement","La nature impose son calendrier : s''adapter, c''est être en sécurité et en harmonie avec le milieu","Pour des raisons touristiques uniquement","Uniquement pour les pêcheurs professionnels"],"correctAnswerIndex":1,"explanation":"Marées, vents, saisons de reproduction conditionnent la sécurité et l''impact des activités. Les connaître permet d''agir au bon moment.","version_enfant":{"question":"Pourquoi on ne part pas sur l''eau à la même heure chaque jour ?","answers":["Le club change l''horaire sans raison","Parce que la marée se décale d''environ 50 minutes chaque jour","Parce que le vent change tous les jours","Il n''y a pas de raison particulière"],"correctAnswerIndex":1,"explanation":"C''est la marée qui commande, pas le club. Elle se décale d''environ 50 minutes chaque jour, donc l''horaire de départ la suit."}}'::jsonb WHERE id = '4882467a-bff6-4adb-a9cb-6de2e7151e28';
UPDATE game_cards SET related_objective_id = '93', data = '{"question":"Quels sens, en dehors de la vue, aident à observer la nature en bord de mer ?","answers":["Uniquement le toucher","L''ouïe (vagues, oiseaux), l''odorat (iode, algues), parfois le toucher","Uniquement l''odorat","Il faut des instruments"],"correctAnswerIndex":1,"explanation":"Un bon observateur mobilise tous ses sens : le bruit de la mer, l''odeur des algues à marée basse, le vent sur la peau.","version_enfant":{"question":"Pour observer la nature au bord de la mer, on utilise seulement les yeux ?","answers":["Oui, seulement les yeux","Non, les oreilles et le nez servent aussi beaucoup","Non, seulement les mains","Il faut fermer les yeux"],"correctAnswerIndex":1,"explanation":"Les yeux ne suffisent pas : le bruit, les odeurs et le vent racontent aussi ce qui se passe ici. L''oreille repère souvent un oiseau avant le regard."}}'::jsonb WHERE id = '742fa95f-7f09-4d2e-8807-da0d4beb9170';
UPDATE game_cards SET related_objective_id = '106', data = '{"question":"Que faut-il observer sur la marée et le courant avant une activité nautique ?","answers":["Uniquement la hauteur de la mer au départ","L''heure de haute/basse mer, l''amplitude (coefficient), les zones de courant fort ou de ressac","La couleur de l''eau uniquement","La direction du vent uniquement"],"correctAnswerIndex":1,"explanation":"Avant toute sortie : heure et coefficient de marée, zones de courant identifiées. Ces informations permettent d''évaluer le risque.","version_enfant":{"question":"Avant de partir, quelles sont les trois choses à vérifier sur la marée ?","answers":["L''heure de la marée, son coefficient, et où le courant sera fort","Juste l''heure de la marée","Juste la couleur de l''eau","Rien, on regarde en arrivant sur place"],"correctAnswerIndex":0,"explanation":"Trois questions avant de partir : à quelle heure sera la marée, quelle est son amplitude, et où le courant sera fort."}}'::jsonb WHERE id = '7aff8cd8-b304-4d6e-8e7c-a8adbef9fbf2';
UPDATE game_cards SET related_objective_id = '61', data = '{"question":"Comment identifier des traces de présence animale sur le littoral ?","answers":["Uniquement par les sons produits par les animaux","Empreintes dans le sable humide, plumes, coquilles ouvertes, algues arrachées","En creusant dans le sable","Impossible sans jumelles"],"correctAnswerIndex":1,"explanation":"Traces de pas, plumes, coquilles percées par des prédateurs, empreintes : le littoral est une lecture continue de la vie animale.","version_enfant":{"question":"Comment sait-on qu''un animal est passé par là, même sans le voir ?","answers":["On ne peut pas le savoir","On cherche ses traces : empreintes, plumes, coquilles ouvertes","Il faut forcément des jumelles","Il faut creuser partout"],"correctAnswerIndex":1,"explanation":"Les animaux laissent des traces : empreintes, plumes, coquilles ouvertes. On lit leur passage même sans les voir."}}'::jsonb WHERE id = 'c5727395-dd7d-4d81-8efd-fefd761540d0';
UPDATE game_cards SET related_objective_id = '72', data = '{"question":"Pourquoi tout ce qui est inhabituel doit-il être signalé ?","answers":["Par obligation légale uniquement","Chaque signalement peut déclencher une action de protection ou de recherche","Uniquement pour une espèce protégée","Uniquement en zone de réserve naturelle"],"correctAnswerIndex":1,"explanation":"Des milliers d''yeux valent mieux qu''un seul. Signaler une pollution ou un animal échoué peut déclencher une intervention rapide.","version_enfant":{"question":"Si tu vois quelque chose de bizarre sur la plage, quelqu''un l''a sûrement déjà signalé ?","answers":["Oui, sûrement","Pas forcément — le signaler peut vraiment servir","Non, ça ne sert à rien de le dire","Seuls les scientifiques peuvent le faire"],"correctAnswerIndex":1,"explanation":"Nos yeux servent à quelque chose : signaler ce qui est anormal peut déclencher une vraie action. Souvent, personne ne l''a fait avant vous."}}'::jsonb WHERE id = 'c76c2fda-c78c-47df-95d4-a8fa4ccf640a';
